import{_ as e,r as s,o,c as l,e as n,a as c,s as u}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Обновление фрагментов - October CMS - 3.x","titleTemplate":false,"description":"Узнайте больше о динамическом обновлении содержимого.","frontmatter":{"subtitle":"Узнайте больше о динамическом обновлении содержимого."},"headers":[{"level":2,"title":"Запрос обновлений фрагментов (Pull)","slug":"запрос-обновлении-фрагментов-pull","link":"#запрос-обновлении-фрагментов-pull","children":[{"level":3,"title":"Самообновляющиеся фрагменты","slug":"самообновляющиеся-фрагменты","link":"#самообновляющиеся-фрагменты","children":[]},{"level":3,"title":"Глобальные обновления фрагментов","slug":"глобальные-обновления-фрагментов","link":"#глобальные-обновления-фрагментов","children":[]}]},{"level":2,"title":"Определение обновления","slug":"определение-обновления","link":"#определение-обновления","children":[{"level":3,"title":"Добавление и вставка содержимого","slug":"добавление-и-вставка-содержимого","link":"#добавление-и-вставка-содержимого","children":[]},{"level":3,"title":"Использование пользовательских HTML-селекторов","slug":"использование-пользовательских-html-селекторов","link":"#использование-пользовательских-html-селекторов","children":[]}]},{"level":2,"title":"Отправка обновлений фрагментов (Push)","slug":"отправка-обновлении-фрагментов-push","link":"#отправка-обновлении-фрагментов-push","children":[]},{"level":2,"title":"Передача переменных фрагментам","slug":"передача-переменных-фрагментам","link":"#передача-переменных-фрагментам","children":[]}],"relativePath":"3.x/ru/cms/ajax/update-partials.md","filePath":"3.x/ru/cms/ajax/update-partials.md"}'),r={name:"3.x/ru/cms/ajax/update-partials.md"};function i(k,a,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Обновление фрагментов",-1)),n(p),a[1]||(a[1]=u(`<p>Когда обработчик выполняется, он может подготавливать фрагменты для обновления на странице, как путём отправки (push), так и путём запроса (pull), которые могут быть отрендерены с предоставленными переменными.</p><h2 id="запрос-обновлении-фрагментов-pull"><a href="#запрос-обновлении-фрагментов-pull" class="header-anchor">#</a> Запрос обновлений фрагментов (Pull)</h2><p>Клиентский браузер может запрашивать обновление фрагментов с сервера при выполнении AJAX-запроса, что считается <em>запросом обновления содержимого</em>.</p><p>С помощью <a href="./../../markup/tag/partial.html">тега <code>{% partial %}</code></a> следующий код рендерит фрагмент <strong>mytime</strong> внутри элемента <code>#myDiv</code> на странице при вызове <a href="./handlers.html">обработчика событий</a> <code>onRefreshTime</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./attributes-api.html">API атрибутов данных</a> использует атрибут <code>data-request-update</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./javascript-api.html">JavaScript API</a> использует опцию конфигурации <code>update</code>:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token comment">// JavaScript API</span>
oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;#mybutton&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;onRefreshTime&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">mytime</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="самообновляющиеся-фрагменты"><a href="#самообновляющиеся-фрагменты" class="header-anchor">#</a> Самообновляющиеся фрагменты</h3><p><a href="./../../markup/tag/ajax-partial.html">Тег <code>{% ajaxPartial %}</code></a> предназначен для рендеринга AJAX-фрагментов.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>При использовании этого тега содержимое автоматически оборачивается в контейнер, что позволяет обновлять фрагмент только по имени. Просто передайте значение <code>true</code> вместо CSS-селектора контейнера.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы также можете использовать имя фрагмента <code>_self</code> для обновления фрагмента изнутри самого себя.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">_self</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Подробнее о теге <code>{% ajaxPartial %}</code> читайте в <a href="./../../markup/tag/ajax-partial.html">статье о Twig-теге AJAX Partial</a>.</p></div><h3 id="глобальные-обновления-фрагментов"><a href="#глобальные-обновления-фрагментов" class="header-anchor">#</a> Глобальные обновления фрагментов</h3><p>В некоторых случаях, например с <a href="./../../cms/features/flash-messages.html">flash-сообщениями</a>, вы можете захотеть включить определённое обновление фрагмента в каждый ответ. Чтобы объединить определение обновления с каждым AJAX-запросом, добавьте мета-тег <code>ajax-request-update</code> в секцию head страницы и установите атрибут content в определение обновления.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ajax-request-update<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ flash-messages: true }<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="определение-обновления"><a href="#определение-обновления" class="header-anchor">#</a> Определение обновления</h2><p>Определение того, что должно быть обновлено, задаётся как JSON-подобный объект, где:</p><ul><li>левая сторона (ключ) — это <strong>имя фрагмента</strong></li><li>правая сторона (значение) — это <strong>целевой элемент</strong> для обновления</li></ul><p>Следующий пример запрашивает обновление элемента <code>#myDiv</code> содержимым фрагмента <strong>mypartial</strong>.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">mypartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Селектор должен начинаться с символа <code>#</code> или <code>.</code>, чтобы быть валидным.</p></div><p>Несколько фрагментов разделяются запятыми.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">firstpartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">secondpartial</span><span class="token operator">:</span> <span class="token string">&#39;#otherDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>Если имя фрагмента содержит слеш или дефис, важно заключить левую сторону в кавычки.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;my-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>Целевой элемент всегда находится справа, так как он также может быть HTML-элементом в JavaScript.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;myDiv&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
</code></pre></div><h3 id="добавление-и-вставка-содержимого"><a href="#добавление-и-вставка-содержимого" class="header-anchor">#</a> Добавление и вставка содержимого</h3><p>Если строка селектора предваряется символом <code>@</code>, содержимое, полученное от сервера, будет добавлено в конец элемента, вместо замены существующего содержимого.</p><p>Если строка селектора предваряется символом <code>^</code>, содержимое будет вставлено в начало.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;@#myDiv&#39;</span> <span class="token punctuation">}</span>

<span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/prepend-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;^#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>Альтернативно, вы можете добавить атрибут <code>data-ajax-update-mode</code> к целевому элементу.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>append<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>prepend<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="использование-пользовательских-html-селекторов"><a href="#использование-пользовательских-html-селекторов" class="header-anchor">#</a> Использование пользовательских HTML-селекторов</h3><p>Если строка селектора начинается с символа <code>=</code>, вы можете использовать любой пользовательский HTML-селектор для нацеливания на элемент.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append&#39;</span><span class="token operator">:</span> <span class="token string">&#39;=[data-field-name=&quot;address&quot;]&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><h2 id="отправка-обновлении-фрагментов-push"><a href="#отправка-обновлении-фрагментов-push" class="header-anchor">#</a> Отправка обновлений фрагментов (Push)</h2><p>Для сравнения, <a href="./handlers.html">AJAX-обработчики</a> могут отправлять обновления содержимого в клиентский браузер со стороны сервера. Для отправки обновления обработчик возвращает массив, где ключ — это HTML-элемент для обновления (с использованием простого CSS-селектора), а значение — содержимое для обновления.</p><div class="custom-block aside"><p>Имя ключа должно начинаться с идентификатора <code>#</code> или символа класса <code>.</code> для инициирования обновления содержимого.</p></div><p>Следующий пример обновит элемент на странице с id <strong>myDiv</strong> содержимым фрагмента <strong>mypartial</strong>. Обработчик <code>onRefreshTime</code> вызывает метод <code>renderPartial</code> для рендеринга содержимого фрагмента в PHP.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRefreshTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#myDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypartial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="передача-переменных-фрагментам"><a href="#передача-переменных-фрагментам" class="header-anchor">#</a> Передача переменных фрагментам</h2><p>В зависимости от контекста выполнения, <a href="./handlers.html">AJAX-обработчик событий</a> предоставляет переменные фрагментам по-разному.</p><ul><li>Используйте <code>$this[]</code> внутри <a href="./../themes/themes.html">PHP-секции</a> страницы или макета.</li><li>Используйте <code>$this-&gt;page[]</code> внутри <a href="./../themes/components.html">класса компонента</a>.</li><li>Используйте <code>$this-&gt;vars[]</code> в <a href="./../../extend/system/controllers.html">области администрирования</a>.</li></ul><p>Эти примеры предоставят переменную <strong>result</strong> фрагменту для каждого контекста:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// From page or layout PHP code section</span>
<span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a component class</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a backend controller or widget</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Это значение может быть доступно с помощью Twig во фрагменте:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Hello world! --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,53))])}const f=e(r,[["render",i]]);export{y as __pageData,f as default};
